--- Config/DefaultGame.ini ---
[/Script/EngineSettings.GeneralProjectSettings]
ProjectName=Pixel Arena
ProjectVersion=0.9.2

[/Script/UnrealEd.ProjectPackagingSettings]
Build=IfProjectHasCode
BuildConfiguration=PPBC_Shipping
UsePakFile=True
bCookAll=False
+MapsToCook=(FilePath="/Game/Maps/Arena")
+DirectoriesToAlwaysCook=(Path="/Game/Data/Effects")
; The palette is only referenced by a string path in LoadObject, so the cooker
; cannot discover it from asset references. Without this it is missing from the pak.
+DirectoriesToAlwaysCook=(Path="/Game/Data/Palettes")
+DirectoriesToNeverCook=(Path="/Game/Dev")


--- Source/PixelArena/ArenaGameMode.h ---
#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	// UPROPERTY keeps the UObject alive: a bare NewObject pointer is not a GC root,
	// so the tracker was purged on the first collection and dereferenced afterwards.
	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker = nullptr;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "UArenaScoreTracker was created with NewObject<UArenaScoreTracker>(this) but stored in a raw pointer without UPROPERTY() in AArenaGameMode (unlike Hud and Palette). The outer does not keep a UObject alive, so the unreferenced tracker was destroyed by the garbage collector ('Collecting garbage: 412 objects purged'), leaving a dangling pointer in AArenaGameMode::ScoreTracker. The next goal called ScoreTracker->AddPoints() into freed memory and crashed with EXCEPTION_ACCESS_VIOLATION at ArenaScoreTracker.cpp:18.",
  "no_colors_cause": "The palette /Game/Data/Palettes/DA_Primary is only referenced by a string path in LoadObject, so the cooker has no asset reference to follow, and Config/DefaultGame.ini listed only /Game/Data/Effects in DirectoriesToAlwaysCook. The asset was therefore never cooked into the pak; at runtime LoadObject failed ('Couldn't find file for package /Game/Data/Palettes/DA_Primary') and AArenaGameMode fell back to the gray palette.",
  "fixes": [
    "Source/PixelArena/ArenaGameMode.h: ScoreTracker is now UPROPERTY() TObjectPtr<UArenaScoreTracker>, making it a GC reference.",
    "Config/DefaultGame.ini: added +DirectoriesToAlwaysCook=(Path=\"/Game/Data/Palettes\") so the palette ships in the pak."
  ],
  "assumptions": [
    "The palette asset lives at /Game/Data/Palettes/DA_Primary, as its load path and the log state; the asset itself is not in this workspace.",
    "ArenaScoreTracker.cpp is not in this workspace, so line 18 was not inspected; the fault is attributed to the dangling ScoreTracker pointer proven by the log ordering (GC at 21:05:13, crash on the first goal at 21:05:27).",
    "The gray fallback is intentional behaviour when the palette is missing, so no source change was made to the fallback itself."
  ]
}
